package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, x, pos int
	fmt.Fscan(reader, &n, &x, &pos)

	// Precompute factorials
	fact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = (fact[i-1] * int64(i)) % MOD
	}

	// Precompute inverse factorials
	invFact := make([]int64, n+1)
	invFact[n] = modPow(fact[n], MOD-2)
	for i := n - 1; i >= 0; i-- {
		invFact[i] = (invFact[i+1] * int64(i+1)) % MOD
	}

	// Simulate binary search to count constraints
	small := 0
	large := 0
	l := 0
	r := n
	for l < r {
		mid := (l + r) / 2
		if mid < pos {
			small++
			l = mid + 1
		} else if mid > pos {
			large++
			r = mid
		} else {
			l = mid + 1
		}
	}

	// Check if we have enough numbers
	if small > x-1 || large > n-x {
		fmt.Println(0)
		return
	}

	// Calculate result
	ans := fact[n-1-small-large]
	ans = (ans * fact[x-1]) % MOD
	ans = (ans * invFact[x-1-small]) % MOD
	ans = (ans * fact[n-x]) % MOD
	ans = (ans * invFact[n-x-large]) % MOD

	fmt.Println(ans)
}

func modPow(a int64, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e%2 == 1 {
			res = (res * a) % MOD
		}
		a = (a * a) % MOD
		e /= 2
	}
	return res
}
